archiveVideo.registerClearedIds(WORLD_FILMS.map((f) => f.id));

/** Every film we have from one country: new world films + tagged titles from other lists (via lookup(id) → film). */
export function countryShelves(country, lookup = () => null) {
  const own = WORLD_FILMS.filter((f) => f.country === country).map((f) => ({ ...f, list: 'world' }));
  const tagged = Object.entries(WORLD_TAGS).filter(([, t]) => t.country === country)
    .map(([id, t]) => { const f = lookup(id); return f ? { ...f, id, country, countryName: t.countryName, genre: t.genre, list: t.list } : null; }).filter(Boolean);
  const all = [...own, ...tagged];
  return TYPES.map((t) => ({ ...t, films: all.filter((f) => f.genre === t.id).sort((a, b) => a.year - b.year) })).filter((t) => t.films.length);
}

export function countryCounts(lookup = () => null) {
  return COUNTRIES.map((c) => ({ ...c, count: countryShelves(c.id, lookup).reduce((n, s) => n + s.films.length, 0), leads: WORLD_LEADS.filter((l) => l.country === c.id).length }))
    .filter((c) => c.count || c.leads);
}

/** a stream tile (same shape as pd-films-more's moreTile) — plays through IA's official player; creator line = country · language */
export function worldTile(f) {
  if (!f || !f.id) return null;
  const id = String(f.id);
  return {
    id, title: f.originalTitle ? `${f.title} (${f.originalTitle})` : f.title, kind: 'film', year: String(f.year || ''),
    creator: [f.countryName, f.language].filter(Boolean).join(' · '),
    thumb: `https://archive.org/services/img/${id}`,
    streamUrl: `https://archive.org/embed/${id}`, embedUrl: `https://archive.org/embed/${id}`,
    license: 'Public domain (curated by SoapBox Stream)', licenseToken: 'public-domain',
    source: 'Internet Archive', attribution: `Internet Archive — ${id}`, posture: 'window',
    details: `https://archive.org/details/${id}`, href: `https://archive.org/details/${id}`,
  };
}
